+    function getSelectionState(question) {
+      const inputs = Array.from(question.querySelectorAll('input[type="checkbox"]'));
+      const selected = inputs.filter((input) => input.checked).map((input) => input.value).sort();
+      const correct = inputs.filter((input) => input.dataset.correct === "true").map((input) => input.value).sort();
+      const isExactMatch =
+        selected.length === correct.length &&
