       font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(56, 189, 248, 0.18), transparent 32%),
         linear-gradient(180deg, var(--bg), #050816 100%);
     }

     a {
       color: inherit;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--accent-strong);
       color: #04111f;
       font-weight: 700;
       transform: translateY(-200%);
       transition: transform 0.2s ease;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     main {
       width: min(100%, 860px);
       margin: 0 auto;
       padding: 4.5rem 1rem 3rem;
     }

     .quiz-shell {
       padding: 1.5rem;
       border: 1px solid var(--surface-border);
       border-radius: 24px;
       background: linear-gradient(180deg, rgba(17, 23, 43, 0.98), rgba(11, 16, 32, 0.96));
       box-shadow: var(--shadow);
       backdrop-filter: blur(12px);
     }

     .eyebrow {
       margin: 0 0 0.5rem;
       color: var(--accent);
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.14em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3rem);
       line-height: 1.1;
     }

     .intro {
       max-width: 60ch;
       margin: 0.85rem 0 0;
       color: var(--muted);
     }

     form {
       margin-top: 1.75rem;
     }

     .form-field + .form-field {
       margin-top: 1.25rem;
     }

     fieldset {
       margin: 0;
       padding: 1.25rem;
       border: 1px solid var(--surface-border);
       border-radius: 18px;
       background: rgba(8, 13, 27, 0.68);
     }

     legend {
       padding: 0 0.35rem;
       font-size: 1.05rem;
       font-weight: 700;
     }

     .help-text {
       margin: 0.5rem 0 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .choice-list {
       display: grid;
       gap: 0.75rem;
       margin-top: 1rem;
     }

     .choice {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
       padding: 0.9rem 1rem;
       border: 1px solid rgba(148, 163, 184, 0.18);
       border-radius: 14px;
       background: rgba(15, 23, 42, 0.75);
       cursor: pointer;
       transition: border-color 0.15s ease, background-color 0.15s ease, transform 0.15s ease;
     }

     .choice:hover {
       border-color: rgba(125, 211, 252, 0.45);
       background: rgba(17, 28, 52, 0.92);
     }

     .choice:focus-within {
       outline: 3px solid var(--focus);
       outline-offset: 2px;
     }

     .choice input {
       margin-top: 0.2rem;
       inline-size: 1.1rem;
       block-size: 1.1rem;
       accent-color: var(--accent-strong);
       flex: 0 0 auto;
     }

     .choice span {
       display: inline-block;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.85rem;
       margin-top: 1.5rem;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.35rem;
       font: inherit;
       font-weight: 700;
       color: #04111f;
       background: linear-gradient(135deg, var(--accent), #a5f3fc);
       box-shadow: 0 10px 24px rgba(56, 189, 248, 0.24);
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.03);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .result {
       margin-top: 1rem;
       padding: 0.95rem 1rem;
       border: 1px solid rgba(148, 163, 184, 0.2);
       border-radius: 14px;
       background: rgba(9, 15, 30, 0.92);
       color: var(--muted);
     }

     .result strong {
       color: var(--text);
     }

     .question--correct fieldset {
       border-color: rgba(52, 211, 153, 0.55);
     }

     .question--incorrect fieldset {
       border-color: rgba(248, 113, 113, 0.55);
     }

     .question--correct legend::after,
     .question--incorrect legend::after {
       margin-left: 0.5rem;
       font-size: 0.85em;
       font-weight: 700;
     }

     .question--correct legend::after {
       content: "Correct";
       color: var(--success);
     }

     .question--incorrect legend::after {
       content: "Check again";
       color: var(--danger);
     }

     @media (max-width: 640px) {
       main {
         padding: 3.5rem 0.75rem 2rem;
       }

       .quiz-shell {
         padding: 1rem;
         border-radius: 20px;
       }

       fieldset {
         padding: 1rem;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       html {
         scroll-behavior: auto;
       }

       *,
       *::before,
       *::after {
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
')

